/* Auto-generated from _site_excluded/supplement-pairings.json. Do not edit by hand. */
window.SUPP_PAIRINGS = [{"id":"p1","members":["Vitamin D3","Vitamin K2 (MK-7)"],"strength":5,"kind":"mechanism-complementary","goal":"Bone density + vascular calcification protection","rationale":"D3 increases intestinal Ca absorption. K2 activates osteocalcin/MGP, directing Ca into bone rather than arteries.","dose":"D3 1,000-2,000 IU + MK-7 90-200 mcg, with fat.","contraindications":["warfarin"],"apart_from":[]},{"id":"p2","members":["Vitamin D3","Calcium","Vitamin K2 (MK-7)"],"strength":5,"kind":"mechanism-complementary","goal":"Post-menopausal bone health (WHI-validated)","rationale":"Calcium + D3 reduces hip fracture risk; K2 ensures deposition into bone.","dose":"Calcium 500-600 mg/dose + D3 1,000-2,000 IU + MK-7 90-200 mcg.","contraindications":["warfarin (for K2)","hypercalcemia"],"apart_from":[]},{"id":"p3","members":["Iron","Vitamin C (moderate dose)"],"strength":5,"kind":"absorption-enhancer","goal":"Maximal non-heme iron absorption","rationale":"Ascorbate reduces Fe3+ to Fe2+ and chelates it for uptake. Increases absorption 2-3x.","dose":"25-50 mg elemental Fe (bisglycinate) + 100-250 mg C on empty stomach.","contraindications":[],"apart_from":["Calcium","Zinc","tea","coffee","dairy"]},{"id":"p4","members":["Collagen peptides","Vitamin C (moderate dose)"],"strength":5,"kind":"cofactor","goal":"Tendon / skin / joint collagen synthesis","rationale":"Vitamin C is a required cofactor for prolyl and lysyl hydroxylases in collagen cross-linking.","dose":"10-15 g collagen + 50 mg C. For tendon rehab, 60 min pre-exercise (Shaw protocol).","contraindications":[],"apart_from":[]},{"id":"p5","members":["L-Theanine","Caffeine (standardised)"],"strength":5,"kind":"synergy","goal":"Sustained attention without jitters","rationale":"Theanine raises alpha-wave activity and blunts caffeine-driven HR/anxiety; RCT-backed 2:1 ratio.","dose":"200 mg theanine + 100 mg caffeine. Morning. No afternoon caffeine.","contraindications":[],"apart_from":[]},{"id":"p6","members":["Zinc","Copper (as glycinate)"],"strength":4,"kind":"depletion-offset","goal":"Prevent copper deficiency from long-term zinc use","rationale":"Zn blocks Cu absorption via metallothionein induction. Long-term Zn >25 mg/day depletes Cu and can cause sideroblastic anemia and myelopathy.","dose":"Zn 25-30 mg + Cu 1-2 mg, taken at different meals.","contraindications":[],"apart_from":[]},{"id":"p7","members":["Curcumin (bioavailable form)","Black pepper extract (piperine)"],"strength":4,"kind":"absorption-enhancer","goal":"Curcumin bioavailability","rationale":"Piperine inhibits hepatic glucuronidation, raising serum curcumin up to 20x. Not needed if using phytosomal or liposomal forms.","dose":"Curcuminoids 250-500 mg + piperine 5 mg with fat.","contraindications":[],"apart_from":[]},{"id":"p8","members":["Probiotics","Fibre (general dietary)"],"strength":4,"kind":"synergy","goal":"Gut colonisation and short-chain fatty acid production","rationale":"Probiotic strains require prebiotic substrate (inulin, acacia, psyllium, resistant starch) to establish and produce SCFAs. Synbiotic concept.","dose":"1-10B CFU strain-specific + 5-10 g soluble fibre daily.","contraindications":[],"apart_from":[]},{"id":"p9","members":["Folate (5-MTHF)","Vitamin B12"],"strength":5,"kind":"cofactor","goal":"Methylation cycle / homocysteine / pregnancy","rationale":"The two feed the same cycle via methionine synthase. High-dose folate masks B12 deficiency and can accelerate neurologic damage.","dose":"400-800 mcg 5-MTHF + 500-1,000 mcg methylcobalamin.","contraindications":[],"apart_from":[]},{"id":"p10","members":["Myo-inositol","D-Chiro Inositol"],"strength":5,"kind":"physiological-ratio","goal":"PCOS: ovulation, insulin sensitivity, androgen reduction","rationale":"Ovarian tissue uses a ~40:1 myo:DCI ratio. High-dose DCI alone worsens oocyte quality (DCI paradox).","dose":"2,000 mg myo + 50 mg DCI (40:1), twice daily.","contraindications":[],"apart_from":[]},{"id":"p11","members":["Lutein + Zeaxanthin"],"strength":5,"kind":"mechanism-complementary","goal":"Macular pigment density / AMD prevention","rationale":"Lutein and zeaxanthin concentrate in different macular regions. AREDS2 formula combines them.","dose":"10 mg L + 2 mg Z with fat.","contraindications":[],"apart_from":[]},{"id":"p12","members":["Alpha-GPC","Aniracetam"],"strength":4,"kind":"side-effect-offset","goal":"Prevent racetam-induced headaches","rationale":"Racetams upregulate ACh turnover; added choline prevents the choline-depletion headache.","dose":"Racetam as prescribed + 300-600 mg alpha-GPC or 250 mg CDP-choline.","contraindications":[],"apart_from":[]},{"id":"p13","members":["Magnesium glycinate","Vitamin D3"],"strength":4,"kind":"cofactor","goal":"Active vitamin D (calcitriol) production","rationale":"Mg is a cofactor for hepatic 25-hydroxylation and renal 1-alpha hydroxylation of D3. Low Mg = low active D even with adequate dose.","dose":"Mg glycinate 200-400 mg + D3 1,000-2,000 IU.","contraindications":[],"apart_from":[]},{"id":"p14","members":["Pea protein","Rice protein"],"strength":4,"kind":"complementary-amino-acids","goal":"Complete plant-protein amino-acid profile","rationale":"Pea is low in Met/Cys; rice is low in Lys. Together they rival whey's leucine / BCAA profile.","dose":"20-40 g combined, ~70:30 pea:rice.","contraindications":[],"apart_from":[]},{"id":"p15","members":["Whey protein","L-Leucine (standalone)"],"strength":3,"kind":"threshold-amplifier","goal":"Maximal muscle protein synthesis in older adults","rationale":"Per-meal leucine must exceed ~2.5 g to trigger mTORC1. Adults over 65 have anabolic resistance and often need 3-4 g.","dose":"20-30 g protein + 2-3 g leucine per meal.","contraindications":[],"apart_from":[]},{"id":"p16","members":["Omega-3 (EPA/DHA)","Vitamin E (mixed tocopherols)"],"strength":2,"kind":"protective","goal":"Reduce oxidation of PUFAs","rationale":"Most omega-3 products already include tocopherol as antioxidant, but high-dose EPA/DHA users benefit from ~15-30 mg mixed tocopherols.","dose":"EPA/DHA 1-4 g + 15-30 mg mixed tocopherols.","contraindications":[],"apart_from":[]},{"id":"p17","members":["CoQ10 (Ubiquinol)","PQQ (Pyrroloquinoline quinone)"],"strength":2,"kind":"mechanism-complementary","goal":"Mitochondrial biogenesis + electron-transport support","rationale":"PQQ appears to promote mitochondrial biogenesis while CoQ10 acts as an electron carrier. Data entry notes the synergy is commonly cited; human trial data for the combination is limited.","dose":"Ubiquinol 100-200 mg + PQQ 10-20 mg with fat.","contraindications":[],"apart_from":[]},{"id":"p18","members":["Elderberry (Sambucus nigra)","Zinc"],"strength":3,"kind":"independent-complementary","goal":"Shorten cold duration (acute)","rationale":"Each has independent RCT evidence for ~2-day reduction in cold duration when started <48 h from onset.","dose":"15 mL elderberry + 75-92 mg Zn (lozenges) for up to 5 days.","contraindications":[],"apart_from":[]},{"id":"p19","members":["Glucosamine / Chondroitin"],"strength":3,"kind":"mechanism-complementary","goal":"Modest cartilage and joint-pain protection in moderate osteoarthritis","rationale":"GAIT trial found the combination outperformed either component alone in the moderate-to-severe pain subgroup.","dose":"Glucosamine sulfate 1,500 mg + chondroitin sulfate 800-1,200 mg.","contraindications":[],"apart_from":[]},{"id":"p20","members":["Boswellia serrata","Curcumin (bioavailable form)"],"strength":3,"kind":"mechanism-complementary","goal":"Joint inflammation (osteoarthritis)","rationale":"Boswellic acids inhibit 5-LOX; curcumin inhibits NF-kB and COX-2. Non-overlapping pathways.","dose":"Boswellia 300 mg + curcumin 500 mg with fat.","contraindications":[],"apart_from":[]},{"id":"p21","members":["Aged garlic extract (Kyolic)","Omega-3 (EPA/DHA)"],"strength":2,"kind":"mechanism-complementary","goal":"Cardiovascular risk reduction","rationale":"Garlic modestly reduces BP and LDL; omega-3 addresses triglycerides and inflammation.","dose":"AGE 600-1,200 mg + EPA/DHA 1-2 g.","contraindications":[],"apart_from":[]},{"id":"p22","members":["Hesperidin","Vitamin C (moderate dose)","Rutin"],"strength":2,"kind":"mechanism-complementary","goal":"Venous tone / capillary fragility","rationale":"Classic European bioflavonoid + C formula for chronic venous insufficiency.","dose":"Hesperidin 500 mg + rutin 500-1,000 mg + C 500 mg.","contraindications":[],"apart_from":[]},{"id":"p23","members":["Ivy leaf extract (Hedera helix)","Thyme extract (Thymus vulgaris)"],"strength":3,"kind":"mechanism-complementary","goal":"Acute bronchitis / cough","rationale":"Both are expectorants; RCTs support the combination for cough frequency and duration.","dose":"Ivy 300 mg + thyme 300-600 mg.","contraindications":[],"apart_from":[]},{"id":"p24","members":["Nicotinamide riboside (NR)","Pterostilbene"],"strength":2,"kind":"mechanism-complementary","goal":"NAD+ precursor + sirtuin activator","rationale":"NR raises NAD+ substrate; pterostilbene activates sirtuins that use it. Basis protocol raised NAD+ and improved liver markers; clinical longevity endpoints unproven.","dose":"NR 250 mg + pterostilbene 50 mg.","contraindications":[],"apart_from":[]},{"id":"p25","members":["Lactoferrin","Iron"],"strength":3,"kind":"absorption-enhancer","goal":"Iron repletion with fewer GI side-effects","rationale":"Lactoferrin binds iron for controlled release, improving hemoglobin response with less GI upset than ferrous sulfate.","dose":"Lactoferrin 100-250 mg + ferrous bisglycinate 25-50 mg.","contraindications":[],"apart_from":[]},{"id":"p26","members":["NAC (N-Acetyl Cysteine)","Glycine"],"strength":3,"kind":"substrate-pair","goal":"Raise intracellular glutathione","rationale":"NAC provides the rate-limiting cysteine; glycine is the other key substrate. The GlyNAC concept shows improved redox in aging pilots.","dose":"NAC 600-1,200 mg + glycine 3 g.","contraindications":[],"apart_from":[]},{"id":"p27","members":["Citrulline (L-citrulline, pure form)","Dietary Nitrate / Beetroot"],"strength":2,"kind":"mechanism-complementary","goal":"Nitric oxide bioavailability for endurance / blood pressure","rationale":"Citrulline via the L-arginine / NOS pathway; nitrate via the nitrate-nitrite-NO pathway. Additive in some small trials.","dose":"Citrulline 6-8 g + beetroot 400-500 mg nitrate, 2-3 h pre-exercise.","contraindications":[],"apart_from":[]},{"id":"p28","members":["Magnesium taurate","Taurine"],"strength":2,"kind":"synergy","goal":"Blood pressure and cardiac rhythm support","rationale":"Mg-taurate already pairs the two, but adding extra taurine (1-3 g) may provide additive cardiac support in some patients.","dose":"","contraindications":[],"apart_from":[]},{"id":"p29","members":["HMB (β-Hydroxy-β-methylbutyrate)","Creatine monohydrate"],"strength":2,"kind":"independent-complementary","goal":"Sarcopenia / older-adult muscle preservation","rationale":"Creatine builds PCr stores and supports strength; HMB suppresses proteolysis. Each has independent evidence; head-to-head combo trials are thin.","dose":"Creatine 3-5 g + HMB 3 g daily.","contraindications":[],"apart_from":[]},{"id":"p30","members":["Calcium","Magnesium","Vitamin D3","Vitamin K2 (MK-7)","Boron"],"strength":4,"kind":"goal-stack","goal":"Comprehensive bone protocol (post-menopausal / fracture risk)","rationale":"Builds on the WHI Ca+D trial; adds Mg (cofactor), K2 (bone deposition), and optional boron for matrix support.","dose":"Ca 500 mg x2/day + Mg 200-400 mg + D3 1,000-2,000 IU + MK-7 90-200 mcg + boron 3 mg.","contraindications":[],"apart_from":[]},{"id":"p31","members":["Calcium hydroxyapatite (MCHC)","Vitamin D3","Vitamin K2 (MK-7)"],"strength":4,"kind":"mechanism-complementary","goal":"Bone density via food-form calcium matrix","rationale":"MCHC carries calcium plus native collagen/phosphate; still requires D3 for absorption and K2 for bone-deposition routing. Variant of p2/p30 for people using whole-bone calcium sources.","dose":"MCHC 1,000 mg/day + D3 1,000-2,000 IU + MK-7 90-200 mcg, with food.","contraindications":["warfarin (for K2)","hypercalcemia"],"apart_from":[]},{"id":"p32","members":["Uridine monophosphate (UMP)","Omega-3 (EPA/DHA)","Choline"],"strength":3,"kind":"mechanism-complementary","goal":"Neuronal membrane synthesis / cognition","rationale":"UMP + DHA + choline together supply all three substrates for phosphatidylcholine in neurons (Wurtman/MIT work, Souvenaid trials). UMP alone is weakly supported; the combination is the evidenced form.","dose":"UMP 250-500 mg + DHA 500-1,000 mg + Alpha-GPC 300 mg or CDP-choline 250 mg.","contraindications":[],"apart_from":[]},{"id":"p33","members":["Tributyrin / Butyrate","Probiotics","Inulin / FOS (prebiotic fibre)"],"strength":2,"kind":"mechanism-complementary","goal":"Gut barrier / short-chain fatty acid support","rationale":"Tributyrin delivers butyrate to the colon; probiotics + prebiotic fibre also produce butyrate via fermentation. Layering a direct donor with substrate-driven production gives continuous SCFA coverage.","dose":"Tributyrin 300-600 mg + 1-10B CFU probiotic + 5-10 g soluble fibre.","contraindications":[],"apart_from":[]},{"id":"p34","members":["Betaine TMG (trimethylglycine)","Folate (5-MTHF)","Vitamin B12","Vitamin B6 (P5P)"],"strength":3,"kind":"mechanism-complementary","goal":"Homocysteine reduction / methylation backup pathway","rationale":"TMG provides methyl groups via the BHMT pathway in liver/kidney; 5-MTHF + B12 drive the methionine synthase pathway everywhere else; B6 supports the transsulfuration branch. Together they cover both arms of homocysteine clearance.","dose":"TMG 1,000-3,000 mg + 5-MTHF 400-800 mcg + methyl-B12 500 mcg + P5P 25-50 mg.","contraindications":[],"apart_from":[]},{"id":"p35","members":["NAC (N-Acetyl Cysteine)","Glycine","Vitamin B6 (P5P)","Zinc"],"strength":3,"kind":"substrate-pair","goal":"GlyNAC extended — glutathione synthesis + transsulfuration support","rationale":"Extends p26. L-cysteine/NAC + glycine are the two limiting substrates for glutathione; P5P and Zn are cofactors for the transsulfuration enzymes (CBS, CSE) that produce endogenous cysteine.","dose":"NAC 600-1,200 mg + glycine 3 g + P5P 25 mg + Zn 15-25 mg (with Cu 1-2 mg if long-term).","contraindications":[],"apart_from":[]},{"id":"p36","members":["Borage oil (GLA)","Omega-3 (EPA/DHA)"],"strength":4,"kind":"side-effect-offset","goal":"Prevent arachidonic-acid buildup from high-dose GLA","rationale":"GLA can be elongated to arachidonic acid (pro-inflammatory) if the pathway is not balanced by EPA/DHA intake. This pairing is more than convenience — it is a safety-relevant balance.","dose":"Borage oil 500-1,000 mg GLA + EPA/DHA 1-2 g.","contraindications":[],"apart_from":[]},{"id":"p37","members":["Quercetin","Luteolin","Kaempferol","Fisetin"],"strength":2,"kind":"goal-stack","goal":"Broad flavonoid / senolytic-adjacent stack","rationale":"Overlapping but non-identical effects on mast cells, NF-kB, and senescent cells. Kaempferol and luteolin entries both explicitly cite quercetin; fisetin has the strongest senolytic evidence.","dose":"Quercetin 500 mg + luteolin 100 mg + kaempferol 50 mg + fisetin 100 mg daily (or fisetin 1,000 mg x2 days/month pulse).","contraindications":[],"apart_from":[]},{"id":"p38","members":["Galacto-oligosaccharides (GOS)","Probiotics"],"strength":4,"kind":"synergy","goal":"Targeted bifidogenic synbiotic","rationale":"GOS selectively feeds bifidobacteria — a specific case of p8 with stronger trial data than generic fibre for raising Bifidobacterium counts.","dose":"GOS 3.5-5 g + Bifidobacterium-containing probiotic 1-10B CFU.","contraindications":[],"apart_from":[]},{"id":"p39","members":["2'-Fucosyllactose (2'-FL HMO)","Galacto-oligosaccharides (GOS)","Probiotics"],"strength":2,"kind":"synergy","goal":"Broad bifidogenic coverage (infant-HMO-style prebiotic)","rationale":"HMOs and GOS feed overlapping but distinct Bifidobacterium species; combining broadens coverage closer to the breast-milk substrate pattern.","dose":"2'-FL 1-3 g + GOS 3-5 g + probiotic 1-10B CFU.","contraindications":[],"apart_from":[]},{"id":"p40","members":["Oat beta-glucan (cholesterol)","Oat avenanthramides"],"strength":2,"kind":"mechanism-complementary","goal":"Complete oat matrix — cholesterol + vascular antioxidant","rationale":"Beta-glucan handles LDL via bile-acid sequestration; avenanthramides add endothelial antioxidant activity. Whole oats deliver both; isolated supplementation loses one.","dose":"Beta-glucan 3-10 g + avenanthramides (dose not standardised — whole oat sources preferred).","contraindications":[],"apart_from":[]},{"id":"p41","members":["Cluster dextrin (HBCD)","EAAs (Essential amino acids)","Electrolyte complex (Na/K/Mg)"],"strength":3,"kind":"goal-stack","goal":"Intra-workout fuelling for long/endurance sessions","rationale":"HBCD supplies rapid low-osmolality carbs; EAAs supply amino-acid substrate without requiring digestion; electrolytes replace sweat losses. Common endurance protocol.","dose":"HBCD 30-60 g/h + EAAs 10-15 g + electrolytes per sweat rate.","contraindications":[],"apart_from":[]},{"id":"p42","members":["Adenosylcobalamin (dibencozide)","Methylcobalamin (high-dose neurological)"],"strength":3,"kind":"mechanism-complementary","goal":"Comprehensive B12 coverage (both active coenzyme forms)","rationale":"Adenosyl-B12 is the mitochondrial coenzyme for methylmalonyl-CoA mutase; methyl-B12 is the cytosolic cofactor for methionine synthase. The body needs both; supplementing both avoids relying on intracellular conversion.","dose":"Adeno-B12 1-5 mg + methyl-B12 1-5 mg, sublingual, daily or weekly.","contraindications":[],"apart_from":[]},{"id":"p43","members":["Acerola cherry extract","Rutin","Hesperidin","Quercetin"],"strength":2,"kind":"mechanism-complementary","goal":"Food-matrix vitamin C with capillary/vascular bioflavonoids","rationale":"Food-matrix variant of p22. Acerola provides ascorbate in a bioflavonoid context, mirroring traditional European venotropic formulas.","dose":"Acerola 500-1,000 mg (std. 17-25% C) + rutin 500 mg + hesperidin 500 mg + quercetin 500 mg.","contraindications":[],"apart_from":[]},{"id":"p44","members":["Magnolia bark (honokiol + magnolol)","Ashwagandha (KSM-66)","L-Theanine"],"strength":2,"kind":"goal-stack","goal":"Evening wind-down / stress-reducing sleep formula","rationale":"Non-sedative, non-GABAergic stack: magnolia (anxiolytic via GABA-A modulation + cortisol), ashwagandha (cortisol reduction), theanine (alpha-waves). Often combined in pre-sleep formulas.","dose":"Magnolia 200-400 mg + KSM-66 ashwagandha 300-600 mg + theanine 100-200 mg, 60 min pre-bed.","contraindications":["thyroid hormone (for ashwagandha)","sedatives / benzodiazepines"],"apart_from":[]},{"id":"p45","members":["Cistanche tubulosa (Rou Cong Rong)","Horny goat weed (Epimedium)"],"strength":1,"kind":"goal-stack","goal":"Traditional TCM vitality / libido / cognition formula","rationale":"Classical Chinese herbal pairing. Mechanisms are preliminary and human RCT data is limited; label as traditional-use.","dose":"Cistanche 300-1,000 mg + epimedium 250-1,000 mg.","contraindications":[],"apart_from":[]},{"id":"p46","members":["Protocatechuic acid","Quercetin","Other polyphenols"],"strength":1,"kind":"goal-stack","goal":"Broad polyphenol antioxidant coverage","rationale":"Non-overlapping polyphenol targets; mostly additive. Clinical endpoints for the specific pair are thin.","dose":"Dose not well-standardised; typically food-form or extract blend.","contraindications":[],"apart_from":[]},{"id":"p47","members":["Ferulic acid","Vitamin C (moderate dose)","Vitamin E (mixed tocopherols)"],"strength":3,"kind":"mechanism-complementary","goal":"Topical (and oral-adjacent) UV / oxidative-stress protection","rationale":"The classical Duke dermatology stack for skin antioxidant protection; ferulic acid stabilises C and E in formulation and extends photoprotective effect. Topical evidence is strongest; oral synergy extrapolated.","dose":"Topical serum: ferulic acid 0.5% + L-ascorbic acid 15% + tocopherol 1%. Oral: ferulic acid 250 mg + C 500 mg + E 15-30 mg mixed tocopherols.","contraindications":[],"apart_from":[]},{"id":"p48","members":["Phytosterols (beta-sitosterol complex)","Oat beta-glucan (cholesterol)"],"strength":3,"kind":"mechanism-complementary","goal":"Additive LDL-C reduction","rationale":"Phytosterols displace cholesterol at intestinal absorption; beta-glucan sequesters bile acids. Different mechanisms; FDA recognises both as authorised cholesterol-lowering health claims. Additive ~5-10% each.","dose":"Phytosterols 2 g/day (with fat-containing meal) + beta-glucan 3-10 g/day.","contraindications":[],"apart_from":[]},{"id":"p49","members":["L-Arginine","L-Ornithine"],"strength":2,"kind":"synergy","goal":"Growth-hormone support / ammonia clearance","rationale":"Ornithine and arginine recycle through the urea cycle; the combination shows larger GH responses in older trials than either alone. Modern practice often prefers L-citrulline for the NO endpoint.","dose":"L-Arg 3-6 g + L-Orn 2-5 g, pre-bed.","contraindications":[],"apart_from":[]},{"id":"p50","members":["Pantethine","Omega-3 (EPA/DHA)","Phytosterols (beta-sitosterol complex)"],"strength":2,"kind":"goal-stack","goal":"Non-statin lipid management","rationale":"Pantethine modestly lowers LDL and TG; omega-3 targets TG; phytosterols lower LDL. Non-overlapping mechanisms for combined lipid panels.","dose":"Pantethine 600-900 mg + EPA/DHA 1-2 g + phytosterols 2 g.","contraindications":[],"apart_from":[]},{"id":"p51","members":["Calcium D-glucarate","DIM (Diindolylmethane)"],"strength":2,"kind":"mechanism-complementary","goal":"Estrogen metabolism / Phase II conjugation support","rationale":"Ca-D-glucarate inhibits beta-glucuronidase (reducing estrogen reabsorption); DIM shifts hydroxylation toward less-active 2-OH estrogens. Popular combo in functional-medicine estrogen-clearance protocols; direct combo RCTs are limited.","dose":"Ca-D-glucarate 500-1,000 mg + DIM 100-200 mg.","contraindications":["pregnancy","hormone-modulating drugs (consult clinician)"],"apart_from":[]},{"id":"p52","members":["D-Mannose","Cranberry PAC (A-type proanthocyanidins)"],"strength":3,"kind":"mechanism-complementary","goal":"Recurrent UTI prophylaxis","rationale":"D-Mannose blocks E. coli FimH adhesin at the bladder wall; cranberry PACs also inhibit bacterial adherence via a related mechanism. Both are listed in UTI guidelines; combination is additive.","dose":"D-Mannose 2 g 1-2x/day + cranberry extract 500 mg (std. PACs 36 mg).","contraindications":[],"apart_from":[]},{"id":"p53","members":["L-Lysine","Vitamin C (moderate dose)"],"strength":2,"kind":"mechanism-complementary","goal":"Collagen / connective-tissue support (Pauling concept)","rationale":"Both are substrates/cofactors for collagen synthesis. Lysine is the limiting amino acid for collagen cross-links; C is the cofactor. Cardiovascular-endpoint claims are unproven, but the connective-tissue rationale is sound.","dose":"L-Lysine 1-3 g + Vitamin C 500-1,000 mg.","contraindications":[],"apart_from":[]},{"id":"p54","members":["Maqui berry (Aristotelia chilensis)","Lutein + Zeaxanthin"],"strength":1,"kind":"independent-complementary","goal":"Dry-eye / macular support","rationale":"Maqui delphinidins have small dry-eye trials; lutein/zeaxanthin are the AREDS2 pigments. Independent evidence bases; combination not RCT-tested.","dose":"Maqui 60-120 mg + lutein 10 mg + zeaxanthin 2 mg.","contraindications":[],"apart_from":[]},{"id":"p55","members":["Creatine monohydrate","Whey protein","Carbohydrate"],"strength":3,"kind":"absorption-enhancer","goal":"Maximise creatine uptake into muscle","rationale":"Insulin drives creatine transport into muscle. Taking creatine with protein + carbs (post-workout or meal) raises muscle creatine accumulation vs fasted dosing.","dose":"Creatine 3-5 g + whey 20-30 g + 30-50 g carbohydrate, post-workout.","contraindications":[],"apart_from":[]},{"id":"p56","members":["Casein protein","Whey protein"],"strength":3,"kind":"temporal-complementary","goal":"24-hour muscle protein synthesis coverage","rationale":"Whey is rapidly digested and spikes plasma amino acids — ideal post-workout to drive an acute MPS response. Casein clots in the stomach and releases amino acids slowly over ~7 h — ideal pre-bed to suppress overnight proteolysis. Layering the two by timing (not by mixing) covers both the post-exercise anabolic window and the overnight fasted period.","dose":"Whey 20-30 g within 1-2 h post-workout + casein 30-40 g 30-60 min pre-bed on training days.","contraindications":[],"apart_from":[]},{"id":"p57","members":["Ashwagandha (KSM-66)","Rhodiola rosea"],"strength":3,"kind":"goal-stack","goal":"Adaptogen stack — calming + activating","rationale":"KSM-66 ashwagandha lowers cortisol and supports recovery from chronic stress; Rhodiola rosea is a stimulating adaptogen that supports energy and mental endurance. Complementary mechanisms (GABAergic/HPA-axis dampening + monoaminergic/fatigue resistance). No head-to-head RCT of the combination, but both have independent evidence and the combination is in clinical use.","dose":"KSM-66 ashwagandha 300-600 mg/day (food, AM or PM) + Rhodiola rosea 200-400 mg/day (empty stomach, AM only). Cycle 8-12 weeks on, 2-4 weeks off.","contraindications":["thyroid hormone (ashwagandha)","benzodiazepines / sedatives","immunosuppressants (ashwagandha)","bipolar disorder (Rhodiola)"],"apart_from":[]},{"id":"p58","members":["Hyaluronic acid (oral)","Chondroitin sulfate (standalone)"],"strength":2,"kind":"mechanism-complementary","goal":"Joint lubrication + cartilage matrix support","rationale":"Oral HA contributes to synovial fluid viscosity and joint lubrication; chondroitin supports cartilage GAG matrix and modestly reduces joint pain. A 2024 RCT of the combination found reduced knee stiffness and improved mobility at 3 months. Either alone is modest; combined evidence is the entry's basis.","dose":"HA 80-200 mg/day (low-MW oral) + chondroitin sulfate 400-800 mg/day, with food. Allow 3 months.","contraindications":[],"apart_from":[]},{"id":"p59","members":["Theacrine (TeaCrine)","Caffeine (standardised)"],"strength":3,"kind":"synergy","goal":"Energy and focus without tolerance buildup or cardiovascular stimulation","rationale":"Distinct from p5 (L-theanine + caffeine). Theacrine acts on adenosine and dopaminergic pathways with minimal HR/BP effect and shows no tolerance even after 8 weeks of daily use. Combining with caffeine extends effective duration and broadens the neurochemical hit without the jitter or tolerance penalty. Useful when L-theanine has been tried and the user wants a longer-duration option.","dose":"Theacrine 100-200 mg + caffeine 50-150 mg, morning or early afternoon. Avoid PM dosing.","contraindications":["anxiety disorders","uncontrolled hypertension (caffeine portion)"],"apart_from":[]},{"id":"p60","members":["Proline (L-Proline)","Vitamin C (moderate dose)","Glycine"],"strength":2,"kind":"substrate-cofactor-stack","goal":"Comprehensive collagen-synthesis substrate triad","rationale":"Proline (~28% of collagen residues) and glycine (~33%) are the two dominant amino acids in the collagen triple helix; vitamin C is the obligate cofactor for prolyl/lysyl hydroxylases. Supplementing all three together provides both substrate and cofactor and is more rationale-driven than collagen + C alone (p4) for users who do not consume collagen peptides.","dose":"L-Proline 500-2,000 mg + Vitamin C 500 mg + Glycine 3-10 g daily.","contraindications":[],"apart_from":[]},{"id":"p61","members":["Carnosyn beta-alanine (sustained release)","Creatine monohydrate"],"strength":3,"kind":"independent-complementary","goal":"High-intensity / sprint / strength-endurance performance","rationale":"Independent and additive ergogenic mechanisms. Beta-alanine raises muscle carnosine, buffering H+ during 1-10 min efforts. Creatine raises phosphocreatine, supporting <30 s maximal efforts and total work output. Stacking covers both ATP-PCr and glycolytic energy systems. Multiple meta-analyses support each individually; combination is standard sports-nutrition practice.","dose":"Beta-alanine 3.2-6.4 g/day (split or sustained-release) + Creatine monohydrate 3-5 g/day. Beta-alanine requires 4-6 weeks loading.","contraindications":[],"apart_from":[]},{"id":"p62","members":["Red sage / Danshen (Salvia miltiorrhiza)","Sanqi (Panax notoginseng)"],"strength":1,"kind":"traditional-formula","goal":"TCM cardiovascular / circulation support","rationale":"Classical TCM cardiovascular pairing (often as 'Compound Danshen Dripping Pill'). Both have anti-platelet and vasodilatory activity in lab and Chinese clinical studies; independent replication outside China is limited. Listed for completeness — additive bleeding risk is the dominant practical consideration.","dose":"Dan Shen 1,500-3,000 mg/day + Sanqi 500-1,500 mg/day standardised extract.","contraindications":["warfarin / DOAC / aspirin / NSAID (additive bleeding)","pre-surgical period (stop ≥2 weeks prior)"],"apart_from":[]},{"id":"p63","members":["Beta-Alanine","Creatine monohydrate"],"strength":4,"kind":"synergy","goal":"Anaerobic performance + endurance buffering","rationale":"Creatine increases short-burst phosphocreatine; beta-alanine raises muscle carnosine to buffer H+ in 1-4 min efforts. Loaded together cover overlapping intensity zones.","dose":"Creatine 3-5 g/day + Beta-alanine 3.2-6.4 g/day in divided 800 mg doses to minimise paresthesia.","contraindications":[],"apart_from":[]},{"id":"p64","members":["Calcium","Magnesium","Zinc"],"strength":4,"kind":"absorption-conflict","goal":"Mineral absorption competition warning","rationale":"Divalent cations (Ca2+, Mg2+, Zn2+) compete for the same divalent metal transporters (DMT-1) in the intestine. Doses >800 mg of any one significantly reduce uptake of the others.","dose":"Take large mineral doses (>500 mg) at least 2 hours apart. Smaller everyday doses can usually be co-ingested without major loss.","contraindications":[],"apart_from":[]},{"id":"p65","members":["Lactobacillus rhamnosus GG","Acacia fiber (prebiotic)"],"strength":3,"kind":"synergy","goal":"Synbiotic gut support","rationale":"Selective fermentation of acacia by Lactobacillus enhances strain persistence and short-chain-fatty-acid production.","dose":"1-10 billion CFU LGG + 5-15 g acacia, separately or in same dose with cool water (heat kills probiotics).","contraindications":[],"apart_from":[]},{"id":"p66","members":["Quercetin","Bromelain"],"strength":3,"kind":"absorption-enhancer","goal":"Quercetin absorption + anti-inflammatory synergy","rationale":"Bromelain enzymes increase intestinal absorption of quercetin; both have additive mast-cell stabilizing effects in allergy/inflammation.","dose":"Quercetin 500 mg + Bromelain 100-250 mg, on empty stomach.","contraindications":[],"apart_from":[]},{"id":"p67","members":["Vitamin C (moderate dose)","Zinc"],"strength":3,"kind":"synergy","goal":"Common-cold severity reduction","rationale":"Independent meta-analyses show modest cold-symptom reduction; combining at first symptom is the most-studied protocol.","dose":"Vitamin C 1000 mg + Zinc lozenge 13-23 mg every 2 hours within 24 h of symptom onset (max 5 days).","contraindications":[],"apart_from":[]},{"id":"p68","members":["Magnesium","Pyridoxal 5-phosphate (P5P)"],"strength":3,"kind":"synergy","goal":"PMS symptom reduction","rationale":"Two RCTs (Fathizadeh 2010; De Souza 2000) show greater PMS symptom reduction with Mg + B6 vs Mg alone.","dose":"Magnesium 200-360 mg + P5P 40-80 mg from luteal phase through menstruation.","contraindications":[],"apart_from":[]},{"id":"p69","members":["Choline","Omega-3 (EPA/DHA)"],"strength":4,"kind":"mechanism-complementary","goal":"Brain phospholipid synthesis (especially pregnancy/infancy)","rationale":"Phosphatidylcholine + DHA together build neuronal membranes; large prenatal cohorts find compounded cognitive benefits in offspring.","dose":"Choline 450-550 mg + DHA 200-300 mg/day during pregnancy and lactation.","contraindications":[],"apart_from":[]},{"id":"p70","members":["Iron"],"strength":5,"kind":"absorption-conflict","goal":"Iron absorption protection","rationale":"Tannins (tea/coffee), divalent cations, and casein phosphopeptides each significantly reduce non-heme iron uptake.","dose":"Take iron on empty stomach with vitamin C; separate from calcium, zinc, magnesium, dairy, tea, coffee by 2 hours.","contraindications":[],"apart_from":["Calcium","Zinc","tea","coffee","dairy","Magnesium"]},{"id":"p71","members":["Vitamin D3","Magnesium"],"strength":4,"kind":"cofactor","goal":"Vitamin D activation","rationale":"Magnesium is a cofactor for the enzymes converting vitamin D to its active form. Vitamin D supplementation increases magnesium needs.","dose":"Vitamin D3 1000-2000 IU + Magnesium 200-400 mg/day with food.","contraindications":[],"apart_from":[]},{"id":"p72","members":["Berberine","Bergamot citrus polyphenol extract"],"strength":3,"kind":"synergy","goal":"Lipid + glucose support without statin","rationale":"Berberine activates AMPK; bergamot inhibits HMG-CoA reductase via brutieridin/melitidin. Italian RCTs combine for additive LDL reduction.","dose":"Berberine 500 mg 2-3×/day + Bergamot 500-1000 mg/day with meals.","contraindications":[],"apart_from":[]},{"id":"p73","members":["Citrulline malate","Beta-Alanine"],"strength":3,"kind":"synergy","goal":"Resistance + endurance pre-workout stack","rationale":"Citrulline boosts NO/blood flow during reps; beta-alanine buffers H+ for the 1-4 min ATP-PC + glycolytic crossover.","dose":"Citrulline malate 6-8 g + Beta-alanine 3.2 g, 30-45 min pre-workout.","contraindications":[],"apart_from":[]},{"id":"p74","members":["Lutein + Zeaxanthin","Omega-3 (EPA/DHA)"],"strength":4,"kind":"synergy","goal":"Macular pigment density","rationale":"AREDS2 + LUTEGA trials: omega-3 enhances retinal carotenoid uptake. Effect on macular pigment optical density is greater than either alone.","dose":"Lutein 10 mg + Zeaxanthin 2 mg + DHA 350 mg/day with a fatty meal.","contraindications":[],"apart_from":[]},{"id":"p75","members":["Selenium","Iodine"],"strength":4,"kind":"cofactor","goal":"Thyroid hormone production support","rationale":"Iodine is the substrate; selenium-dependent iodothyronine deiodinases convert T4 to T3 and protect the gland from peroxide damage.","dose":"Selenium 100-200 mcg + Iodine 150 mcg/day. Higher iodine without selenium can worsen autoimmune thyroiditis.","contraindications":[],"apart_from":[]},{"id":"p76","members":["Glycine","Magnesium glycinate"],"strength":3,"kind":"synergy","goal":"Sleep onset + maintenance","rationale":"Glycine lowers core body temperature; magnesium activates GABA receptors. Bambico/Inagawa trials show subjective sleep improvement.","dose":"Glycine 3 g + Magnesium glycinate 300-400 mg, 30-60 min before bed.","contraindications":[],"apart_from":[]},{"id":"p77","members":["L-Theanine","Magnesium"],"strength":3,"kind":"synergy","goal":"Anxiety + stress reduction","rationale":"Both raise GABA tone via different routes (theanine ionotropic; magnesium NMDA antagonism + GABA-A modulation).","dose":"L-Theanine 200 mg + Magnesium 200-300 mg, evening or under acute stress.","contraindications":[],"apart_from":[]},{"id":"p78","members":["Saffron (Crocus sativus)","Curcumin (bioavailable form)"],"strength":3,"kind":"synergy","goal":"Adjunct depression support","rationale":"Both modulate inflammation + monoamine signalling; combined saffron-curcumin has equivalent efficacy to fluoxetine 20 mg in mild-moderate depression (Akhondzadeh trial).","dose":"Saffron 30 mg + Curcumin 500-1000 mg/day; 8-12 week trial.","contraindications":["SSRI/SNRI","MAOI","lithium"],"apart_from":[]},{"id":"p79","members":["Magnesium glycinate","Vitamin B6 (P5P)"],"strength":4,"kind":"cofactor","goal":"Magnesium uptake + cofactor activation for ~300 enzymes","rationale":"B6 (pyridoxal-5-phosphate) is required for many magnesium-dependent enzymes; trials show greater PMS, anxiety, and migraine benefit when paired vs. magnesium alone.","dose":"Magnesium glycinate 200-400 mg + P5P 25-50 mg/day, evening with food.","contraindications":[],"apart_from":[]},{"id":"p80","members":["Vitamin D3","Vitamin K2 (MK-7)","Magnesium glycinate"],"strength":5,"kind":"mechanism-complementary","goal":"Bone deposition triad — calcium absorbed (D3), directed to bone (K2), enzymes activated (Mg)","rationale":"Magnesium is the cofactor that activates vitamin D and converts inactive osteocalcin; K2 then directs the calcium D3 absorbs into bone instead of arteries.","dose":"D3 1000-2000 IU + MK-7 100-200 mcg + Mg glycinate 200-400 mg, with the largest meal.","contraindications":["warfarin (for K2)"],"apart_from":[]},{"id":"p81","members":["Iron","Calcium"],"strength":5,"kind":"absorption-conflict","goal":"Avoid mineral absorption conflict","rationale":"Calcium reduces non-heme iron absorption by up to 60% via DMT-1 competition. Even ~165 mg calcium with iron blocks half the iron uptake.","dose":"Separate iron and calcium doses by ≥2 hours (and avoid dairy with iron).","contraindications":[],"apart_from":["Calcium","dairy"]},{"id":"p82","members":["Berberine","Milk thistle (Silymarin)"],"strength":3,"kind":"synergy","goal":"Metabolic + hepatoprotection support","rationale":"Berberine improves insulin sensitivity but is hepatically processed; silymarin protects hepatocytes during chronic use. Italian RCTs (Berberol K) combine for NAFLD and metabolic syndrome.","dose":"Berberine 500 mg 2-3×/day + Silymarin 200-400 mg/day with meals.","contraindications":[],"apart_from":[]},{"id":"p83","members":["Whey protein","Creatine monohydrate"],"strength":5,"kind":"synergy","goal":"Hypertrophy + strength gains","rationale":"Largest meta-analysis (Morton 2018) shows protein + creatine adds ~30% more LBM gain than protein alone in trained subjects.","dose":"Whey 0.4 g/kg per meal + Creatine 3-5 g/day, post-workout convenient but timing not critical.","contraindications":[],"apart_from":[]},{"id":"p84","members":["Probiotics","Inulin / FOS (prebiotic fibre)"],"strength":4,"kind":"synergy","goal":"Synbiotic gut colonisation","rationale":"Prebiotic fibre selectively feeds the live bacteria; combined synbiotics outperform probiotics alone for IBS, immune, and metabolic outcomes in several meta-analyses.","dose":"Multi-strain probiotic 5-30 billion CFU + inulin/FOS 5-10 g/day. Start low to avoid bloating.","contraindications":[],"apart_from":[]},{"id":"p85","members":["Folate (5-MTHF)","Methylcobalamin (high-dose neurological)"],"strength":5,"kind":"mechanism-complementary","goal":"Homocysteine reduction + nervous system maintenance","rationale":"Both required for the methionine cycle; deficiency in either causes hyperhomocysteinemia and demyelination. The methylated forms bypass MTHFR and MTRR polymorphisms.","dose":"5-MTHF 400-800 mcg + Methylcobalamin 1000 mcg sublingual daily, AM.","contraindications":[],"apart_from":[]},{"id":"p86","members":["Iron","Vitamin C (moderate dose)","Lactoferrin"],"strength":3,"kind":"synergy","goal":"Gentler iron repletion in deficiency","rationale":"Lactoferrin enhances iron uptake while reducing GI side effects; vitamin C still aids reduction of Fe3+ → Fe2+. Useful in pregnancy and IBD trials.","dose":"Ferrous bisglycinate 25-50 mg + Vitamin C 100-250 mg + Lactoferrin 100-200 mg, on empty stomach.","contraindications":[],"apart_from":["Calcium","Zinc","tea","coffee","dairy"]},{"id":"p87","members":["Magnesium glycinate","Glycine","L-Theanine"],"strength":3,"kind":"synergy","goal":"Sleep onset + anxiety reduction","rationale":"Three different GABAergic / cooling routes converge: glycine lowers core body temp, magnesium activates GABA-A, theanine modulates inhibitory tone via alpha-waves.","dose":"Mg glycinate 300-400 mg + Glycine 3 g + L-Theanine 200 mg, 30-60 min before bed.","contraindications":[],"apart_from":[]}];
